<?php
require __DIR__ . '/includes/tasks.php';
$userId = require_login();
$search = isset($_GET['search']) && is_string($_GET['search']) ? trim($_GET['search']) : '';
$filter = isset($_GET['status']) && is_string($_GET['status']) ? $_GET['status'] : '';
if (!in_array($filter, STATUSES, true)) $filter = '';
$stmt = database()->prepare('SELECT status, COUNT(*) AS total FROM tasks WHERE user_id = ? GROUP BY status'); $stmt->execute([$userId]);
$counts = array_fill_keys(STATUSES, 0); foreach ($stmt as $row) $counts[$row['status']] = (int) $row['total'];
$sql = 'SELECT id, title, description, status, created_at FROM tasks WHERE user_id = ?'; $params = [$userId];
if ($search !== '') { $sql .= " AND title LIKE ? ESCAPE '!'"; $params[] = '%' . str_replace(['!', '%', '_'], ['!!', '!%', '!_'], $search) . '%'; }
if ($filter !== '') { $sql .= ' AND status = ?'; $params[] = $filter; }
$sql .= ' ORDER BY created_at DESC, id DESC'; $stmt = database()->prepare($sql); $stmt->execute($params); $tasks = $stmt->fetchAll();
page_start('My tasks');
?><div class="dashboard-heading"><div><p class="eyebrow">YOUR WORKSPACE</p><h1>My tasks</h1><p class="muted">Hello, <?= e($_SESSION['name'] ?? '') ?>. Here's what's on your plate.</p></div><a class="button" href="task.php">+ New task</a></div>
<section class="stats" aria-label="Task summary"><div class="stat"><span>Total tasks</span><strong><?= array_sum($counts) ?></strong></div><?php foreach (STATUSES as $status): ?><div class="stat"><span><?= e($status) ?></span><strong><?= $counts[$status] ?></strong></div><?php endforeach; ?></section>
<section class="task-section"><div class="section-heading"><div><h2>All tasks</h2><p class="muted">Find and manage your work.</p></div><span class="result-count"><?= count($tasks) ?> <?= count($tasks) === 1 ? 'task' : 'tasks' ?></span></div><form class="filters" method="get"><label class="search"><span class="sr-only">Search by title</span><input type="search" name="search" maxlength="200" value="<?= e($search) ?>" placeholder="Search by title..."></label><label><span class="sr-only">Filter by status</span><select name="status"><option value="">All statuses</option><?php foreach (STATUSES as $status): ?><option value="<?= e($status) ?>" <?= $filter === $status ? 'selected' : '' ?>><?= e($status) ?></option><?php endforeach; ?></select></label><button class="button secondary" type="submit">Apply</button><?php if ($search !== '' || $filter !== ''): ?><a class="reset" href="index.php">Clear</a><?php endif; ?></form>
<?php if (!$tasks): ?><div class="empty"><div class="empty-icon">✓</div><h3><?= $search !== '' || $filter !== '' ? 'No matching tasks' : 'Your list is clear' ?></h3><p class="muted"><?= $search !== '' || $filter !== '' ? 'Try a different search or filter.' : 'Create your first task to get started.' ?></p><?php if ($search === '' && $filter === ''): ?><a href="task.php">Create a task →</a><?php endif; ?></div><?php else: ?><div class="task-list"><?php foreach ($tasks as $task): ?><article class="task-row"><div class="task-content"><div class="task-title"><h3><?= e($task['title']) ?></h3><span class="badge <?= e(strtolower(str_replace(' ', '-', $task['status']))) ?>"><?= e($task['status']) ?></span></div><?php if ($task['description'] !== ''): ?><p class="description"><?= nl2br(e($task['description'])) ?></p><?php endif; ?><p class="date">Created <?= e(date('M j, Y', strtotime($task['created_at']))) ?></p></div><div class="row-actions"><a href="task.php?id=<?= (int) $task['id'] ?>">Edit</a><form method="post" action="delete.php" data-confirm="Delete this task? This cannot be undone."><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $task['id'] ?>"><button class="delete" type="submit">Delete</button></form></div></article><?php endforeach; ?></div><?php endif; ?></section><?php page_end();
